const CheckboxField = ({ id, label, helperText, required, checked, onChange }) => {
  return (
    <div className="form-field">
      <div className="checkbox-wrapper">
        <input
          id={id}
          type="checkbox"
          required={required}
          checked={checked}
          onChange={onChange}
          aria-describedby={helperText ? `${id}-helper` : undefined}
        />
        <label htmlFor={id}>
          {label}
          {required && (
            <span className="required-star" aria-hidden="true">
              *
            </span>
          )}
          {required && <span className="sr-only">(required)</span>}
        </label>
      </div>
      {helperText && (
        <p id={`${id}-helper`} className="helper-text">
          {helperText}
        </p>
      )}
    </div>
  );
};

const ConsentForm = () => {
  const [agreed, setAgreed] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (agreed) {
      setSubmitted(true);
      console.log("Form submitted successfully");
    }
  };

  if (submitted) {
    return (
      <div className="form-container" role="status" aria-live="polite">
        <h1>Thank you</h1>
        <p>Your consent has been recorded.</p>
        <button onClick={() => setSubmitted(false)}>Reset Form</button>
      </div>
    );
  }

  return (
    <div className="form-container">
      <h1>Terms of Use</h1>
      <form onSubmit={handleSubmit}>
        <CheckboxField
          id="terms-consent"
          label="I agree to the Terms of Use"
          helperText="Read and accept our terms to continue."
          required={true}
          checked={agreed}
          onChange={(e) => setAgreed(e.target.checked)}
        />
        <button type="submit">Submit</button>
      </form>
    </div>
  );
};

const App = () => {
  return (
    <main>
      <h1 className="sr-only">Form Submission</h1>
      <ConsentForm />
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(<App />);
